def sembrar(apps, schema_editor):
    ClasificacionTipo = apps.get_model("app", "ClasificacionTipo")
    ValorClasificacionTipo = apps.get_model("app", "ValorClasificacionTipo")
    TipoCobertura = apps.get_model("app", "TipoCobertura")
    TipoClasificacionEcosistema = apps.get_model("app", "TipoClasificacionEcosistema")
    Disturbio = apps.get_model("app", "Disturbio")

    for tipo_cobertura in TipoCobertura.objects.all():
        categoria = _CATEGORIA_POR_CODIGO_COBERTURA.get(tipo_cobertura.codigo, "Cobertura Vegetal")
        nombre_nuevo = _NOMBRE_NUEVO_POR_CODIGO.get(tipo_cobertura.codigo, tipo_cobertura.codigo)
        tipo_nuevo, _creado = ClasificacionTipo.objects.get_or_create(
            nombre=nombre_nuevo, categoria=categoria,
        )
        for valor in tipo_cobertura.valores.all():
            ValorClasificacionTipo.objects.get_or_create(tipo=tipo_nuevo, valor=valor.valor)

    for tipo_eco in TipoClasificacionEcosistema.objects.all():
        tipo_nuevo, _creado = ClasificacionTipo.objects.get_or_create(
            nombre=tipo_eco.nombre, categoria="Ecosistema",
        )
        for valor in tipo_eco.valores.all():
            ValorClasificacionTipo.objects.get_or_create(tipo=tipo_nuevo, valor=valor.valor)

    if Disturbio.objects.exists():
        tipo_disturbio, _creado = ClasificacionTipo.objects.get_or_create(
            nombre="Disturbio", categoria="Disturbio",
        )
        for disturbio in Disturbio.objects.all():
            ValorClasificacionTipo.objects.get_or_create(tipo=tipo_disturbio, valor=disturbio.nombre)

    tipo_uso_actual, _creado = ClasificacionTipo.objects.get_or_create(
        nombre="Uso_actual_colflux", categoria="Uso Suelo",
    )
    for _codigo, etiqueta in _USO_ACTUAL_CHOICES:
        ValorClasificacionTipo.objects.get_or_create(tipo=tipo_uso_actual, valor=etiqueta)


def despoblar(apps, schema_editor):
    ClasificacionTipo = apps.get_model("app", "ClasificacionTipo")
    ClasificacionTipo.objects.all().delete()


